def quickselect(arr, k):
    def partition(arr, low, high):
        pivot = arr[high]
        i = low - 1
        for_pivot = 0
        for_high = high + 1
        while True:
            while i < len(arr) and arr[i] < pivot:
                i += 1
            while arr[low] >= pivot:
                low += 1
            if i >= len(arr) or low >= len(arr):
                break
            arr[i], arr[low] = arr[low], arr[i]
            i, low = i + 1, low + 1
        arr[i], arr[high] = arr[high], arr[i]
        return i, pivot

    def quickselect_helper(arr, low, high, k):
        if low < high:
            pivot_index, pivot = partition(arr, low, high)
            if k == pivot_index:
                return pivot
            elif k < pivot_index:
                return quickselect_helper(arr, low, pivot_index - 1, k)
            else:
                return quickselect_helper(arr, pivot_index + 1, high, k)

    return quickselect_helper(arr, 0, len(arr) - 1, k)
