def count_no_of_ways(n, k):
    # Base case: if there's only one post, there are k ways to paint it
    if n == 1:
        return k
    # If there are two posts, the number of ways is the sum of ways of painting the first post and the second post
    # with different colors
    elif n == 2:
        return k * (k - 1) + k
    else:
        # For more than two posts, the number of ways is the sum of ways of painting the first post and the second post
        # with different colors, and the number of ways of painting the first post and the second post with the same color
        return count_no_of_ways(n - 1, k) * 2 + count_no_of_ways(n - 2, k)

