def find_Max(a, low, high):
    # base case
    if high < low:
        return a[low]
    # find middle element
    mid = low + ((high - low) >> 1)
    # if left side is sorted
    if a[low] <= a[mid]:
        # if right side is sorted
        if a[mid] <= a[high]:
            # if left side is not sorted
            if a[low] < a[mid]:
                return find_Max(a, low, mid - 1)
            # if right side is not sorted
            else:
                return find_Max(a, mid + 1, high)
        else:
            # if left side is not sorted
            if a[low] >= a[mid]:
                return find_Max(a, mid + 1, high)
            else:
                # if right side is not sorted
                if a[low] > a[mid]:
                    return find_Max(a, low, mid - 1)
    else:
        # if left side is not sorted
        if a[low] < a[mid]:
            return find_Max(a, low, mid - 1)
        else:
            # if right side is sorted
            if a[low] <= a[high]:
                return find_Max(a, mid + 1, high)
            else:
                # if left side is sorted
                if a[low] >= a[mid]:
                    return find_Max(a, mid + 1, high)

def find_Max(arr, start, end):
    if start == end:
        return arr[start]
    mid = start + (end - start) // 2
    if arr[start] < arr[mid]:
        if arr[mid] < arr[end]:
            return find_Max(arr, mid, end)
        else:
            return find_Max(arr, start, mid)
    elif arr[mid] < arr[end]:
        return find_Max(arr, start, mid)
    else:
        return find_Max(arr, mid, end)

