from itertools import combinations

def find_combinations(tuples_list):
    result = []
    for combination in combinations(tuples_list, 2):
        for combo in combination:
            if len(combo) == 2:
                sum1 = combo[0][0] + combo[0][1]
                sum2 = combo[1][0] + combo[1][1]
                result.append((sum1, sum2))
