def find_Divisor(start, end):
    # Initialize the maximum divisor to 1
    max_divisor = 1
    # Iterate through all numbers in the interval
    for i in range(start, end + 1):
        # Check if the current number is a divisor of the start
        if start % i == 0:
            # Update the maximum divisor if the current number is greater
            max_divisor = max(max_divisor, i)
    return max_divisor
